await add('infra', 'searxng engines', async () => {
  /* "searxng up" only proves the process is listening — the same trap as the
     sandbox healthz check. It stayed green while all four upstream engines were
     suspended and every web_search silently returned 0 rows. Actually search. */
  const r = await call('GET', 'http://searxng:8080/search', { qs: { q: 'n8n automation', format: 'json' }, timeout: 25000 });
  if (!r.ok) return { ok: false, reason: r.error };
  const b = (r && r.data) || {};
  if (typeof b !== 'object' || !Array.isArray(b.results)) return { ok: false, reason: 'non-JSON response from /search' };
  const dead = b.unresponsive_engines || [];
  const hits = b.results.length;
  const names = dead.map((e) => String(e[0]) + '(' + String(e[1]) + ')');
  if (dead.length && !hits) return { ok: false, reason: dead.length + ' engine(s) suspended, 0 results: ' + names.slice(0, 4).join(', ') };
  if (!hits) return { ok: true, warn: true, detail: '0 results but no engine reported suspension — narrow query or degraded backend' };
  return { ok: true, warn: dead.length > 0, detail: 'results=' + hits + (dead.length ? ' | suspended: ' + names.join(', ') : ' | all engines ok') };
});
