await add('data', 'backup heartbeat fresh', async () => {
  const list = await api('GET', '/data-tables', { limit: 100 });
  const id = ((list.data || []).find((t) => t.name === 'heartbeats') || {}).id;
  if (!id) return { ok: false, reason: 'no table' };
  const rows = await api('GET', '/data-tables/' + id + '/rows', { limit: 50 });
  const bks = (rows.data || []).filter((x) => x.job === 'backup').sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
  if (!bks.length) return { ok: false, reason: 'no backup heartbeat yet' };
  const ageH = (Date.now() - Date.parse(bks[0].createdAt)) / 3600000;
  const age = 'age=' + Math.round(ageH * 10) / 10 + 'h';
  if (bks[0].ok !== 1) return { ok: false, reason: age + ' (last backup reported failure)' };
  // A heartbeat is only evidence if it says what was produced. Anything else
  // is just a ping — and a ping can be faked by hand, which is exactly how
  // this check stayed green for 63 hours with no backup behind it.
  let ev = null;
  try { ev = JSON.parse(String(bks[0].detail || '')); } catch (eP) { ev = null; }
  if (!ev || typeof ev !== 'object') return { ok: false, reason: age + ' heartbeat carries no artifact evidence (legacy ping)' };
  if (Number(ev.n) !== 5) return { ok: false, reason: age + ' only ' + ev.n + '/5 artifacts reported' };
  if (!(Number(ev.bytes) > 0)) return { ok: false, reason: age + ' zero bytes reported' };
  if (String(ev.integrity || '') !== '4/4') return { ok: false, reason: age + ' integrity ' + ev.integrity };
  const detail = age + ' artifacts=' + ev.n + ' bytes=' + ev.bytes + ' integrity=' + ev.integrity + ' stamp=' + String(ev.stamp || '?');
  if (ageH < 30) return { ok: true, detail };
  if (ageH < 40) return { ok: true, warn: true, detail: detail + ' (stale)' };
  return { ok: false, reason: detail };
});

