await add('data', 'kb chunking', async () => {
  // Guards a silent failure: text with no sentence punctuation once arrived as a
  // single chunk, so a whole document shared one vector. It never errored — retrieval
  // just got worse. This makes an oversized chunk fail the daily check instead.
  const r = await call('POST', 'http://localhost:5678/webhook/admin/kb/ingest', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { mode: 'health' }, timeout: 40000 });
  const d = r.data || {};
