  return { ok: true, detail: d.chunks + ' chunks · max ' + d.max_chunk_chars + '/' + d.limit_chars + ' chars' };
});
  const r = await call('GET', 'http://localhost:5678/webhook/admin/delegation', { headers: { Authorization: AUTH }, timeout: 30000 });
  const d = r.data || {};
  if (!r.ok || d.ok !== true) return { ok: false, reason: r.error || 'delegation failed' };
