  const s = d.trend_summary;
  return { ok: true, detail: '14d · done7d=' + s.done_7d + ' · open=' + s.open_now + ' · closure=' + s.closure_rate_7d };
});
  const list = await api('GET', '/data-tables', { limit: 100 });
  const names = {};
  (list.data || []).forEach((t) => { names[t.name] = t.id; });
  if (!names['ops_alerts']) return { ok: false, reason: 'ops_alerts table missing' };
  if (!names['ops_alert_silence']) return { ok: false, reason: 'ops_alert_silence table missing (run deploy.mjs)' };
  const cols = ((await api('GET', '/data-tables/' + names['ops_alerts'] + '/columns')) || []).map((c) => c.name);
  if (cols.indexOf('severity') < 0) return { ok: false, reason: 'ops_alerts.severity missing (run deploy.mjs)' };
