  return { ok: true, detail: 'severity present · silenced=' + (s.data.silenced ? 'yes' : 'no') };
});
  const list = await api('GET', '/data-tables', { limit: 100 });
  const ex = ((list.data || []).find((t) => t.name === 'chat_executions') || {}).id;
  if (!ex) return { ok: false, reason: 'chat_executions table missing' };
