await add('infra', 'tool contract', async () => {
  // 侧车在 /healthz 自报工具名；网关侧快照由 deploy.mjs 写入 tool_contract 表。
  // 两边不一致 = 有人只改了一侧：模型会出现「看得到工具但参数丢失」，且不会报错。
  const h = await call('GET', 'http://stream-bridge:3211/healthz', { timeout: 15000 });
  const live = (h.ok && h.data && Array.isArray(h.data.tools)) ? h.data.tools : null;
  if (!live) return { ok: false, reason: h.error || 'sidecar does not report tools' };
  const list = await api('GET', '/data-tables', { limit: 100 });
  const tid = ((list.data || []).find((t) => t.name === 'tool_contract') || {}).id;
  if (!tid) return { ok: false, reason: 'tool_contract table missing (run deploy.mjs)' };
  const rows = ((await api('GET', '/data-tables/' + tid + '/rows', { limit: 20 })).data) || [];
  const gw = rows.find((r) => r.side === 'gateway');
  if (!gw) return { ok: false, reason: 'no gateway snapshot yet (run deploy.mjs)' };
  const gwSet = new Set(String(gw.tools || '').split(',').map((s) => s.trim()).filter(Boolean));
  const liveSet = new Set(live);
  const onlyGw = Array.from(gwSet).filter((x) => !liveSet.has(x));
  const onlyLive = Array.from(liveSet).filter((x) => !gwSet.has(x));
  if (onlyGw.length || onlyLive.length) {
    return { ok: false, reason: 'gateway-only=[' + onlyGw.join(',') + '] sidecar-only=[' + onlyLive.join(',') + ']' };
  }
  return { ok: true, detail: live.length + ' tools in sync' };
});
  const r = await call('POST', 'http://localhost:5678/webhook/admin/lobehub-config', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { action: 'status' }, timeout: 40000 });
